"""Spring Boot MVC examples with pinned parent and isolated loopback server."""
import json
import hashlib
from catalog_support import Book,ROOT


def save_verified(book):
    from expansion_support import apply_errors
    apply_errors(book)
    evidence=ROOT/'tools/expansion-spring-verification.json'
    cached=json.loads(evidence.read_text(encoding='utf-8')) if evidence.exists() else {}
    for recipe in book.recipes:
        proof=cached.get(recipe['id'])
        current={asset['id']:hashlib.sha256(asset['content'].encode()).hexdigest() for asset in recipe['assets']}
        if proof and proof.get('hashes')==current:recipe['verification']=proof['verification']
    book.save()

