        if key=='deploy':
            data['src/main/resources/application-demo.properties']='atlas.channel=didattico\n'
            data['src/main/java/it/atlas/DemoController.java']=IMPORTS+'@RestController public class DemoController { @Value("${atlas.channel:local}") private String channel; @GetMapping("/channel") public Map<String,String> channel(){return Map.of("channel",channel);} }\n'
            guide+=' Verifica GET http://127.0.0.1:8086/channel: con profilo demo restituisce channel=didattico; senza profilo restituisce local.'
